'use client';

/**
 * @file index.ts
 * @input Layer hooks and components
 * @output Exports all Layer module public API
 * @position Entry point for Layer module
 *
 * SYNC: When adding new Layer files, update exports here
 *
 * NOTE: Popover, HoverCard, and Tooltip have been moved to their own
 * top-level directories. They are re-exported here for backward compatibility.
 * New code should import from @astryxdesign/core/Popover, @astryxdesign/core/HoverCard,
 * or @astryxdesign/core/Tooltip directly.
 */

// Core layer hook (remains in Layer)
export {useLayer} from './useLayer';
export type {
  LayerAlignment,
  LayerPlacement,
  ContextRenderProps,
  FixedRenderProps,
  ContextLayerOptions,
  FixedLayerOptions,
  ContextLayerReturn,
  FixedLayerReturn,
} from './useLayer';

// Layer dismissal stack — one Escape owner for every overlay family
export {useLayerDismissal} from './useLayerDismissal';
export type {
  LayerEscapeBehavior,
  UseLayerDismissalOptions,
  UseLayerDismissalReturn,
} from './useLayerDismissal';
export {LayerDepthProvider} from './LayerDepthContext';

// Shared touch behavior for the hover layers
export {useTouchTrigger, isActionTrigger} from './useTouchTrigger';
export type {
  LayerTouchTrigger,
  UseTouchTriggerOptions,
  UseTouchTriggerReturn,
} from './useTouchTrigger';

// Layer provider
export {LayerProvider} from './LayerProvider';
export type {LayerProviderProps} from './LayerProvider';
export {LayerContext, useLayerContext} from './LayerContext';
export type {
  LayerContextValue,
  LayerInset,
  LayerToastConfig,
} from './LayerContext';

// Shared entry animation styles for layer-based components
export {layerAnimations} from './layerAnimations.stylex';

// Re-export Popover from new location (backward compat)
export {usePopover, Popover} from '@astryxdesign/core/Popover';
export type {
  UsePopoverOptions,
  UsePopoverReturn,
  PopoverProps,
} from '@astryxdesign/core/Popover';

// Re-export HoverCard from new location (backward compat)
export {useHoverCard, HoverCard} from '@astryxdesign/core/HoverCard';
export type {
  HoverCardFocusTrigger,
  HoverCardTouchTrigger,
  HoverCardOptions,
  HoverCardReturn,
  HoverCardProps,
} from '@astryxdesign/core/HoverCard';

// Re-export Tooltip from new location (backward compat)
export {useTooltip, Tooltip} from '@astryxdesign/core/Tooltip';
export type {
  TooltipFocusTrigger,
  TooltipTouchTrigger,
  TooltipOptions,
  TooltipReturn,
  TooltipProps,
} from '@astryxdesign/core/Tooltip';

// Copyright (c) Meta Platforms, Inc. and affiliates.

/**
 * @file layerAnimations.stylex.ts
 * @input Uses StyleX, theme duration/easing tokens, the Reduce Motion fade
 *   constants
 * @output Exports shared entry animation styles for layer-based components
 * @position Shared animation primitives; consumed by DropdownMenu, Popover,
 *   HoverCard, Tooltip, Selector, and any component using useLayer
 *
 * Provides opt-in entry animations for popover/layer components. Apply one
 * to the element that fills the layer (its surface), not to the layer.
 * Chromium lays an anchored layer out again on each frame that its own
 * style animates. On the layer the entrance still plays, at that cost.
 *
 * @example
 * ```
 * import {layerAnimations} from '../Layer/layerAnimations.stylex';
 *
 * // Direction-aware (for components that know placement):
 * layer.render(
 *   <div {...stylex.props(styles.surface, layerAnimations[placement])}>
 *     <Content />
 *   </div>,
 * );
 *
 * // usePopover's surface takes the hook's `xstyle`:
 * const popover = usePopover({xstyle: layerAnimations.below});
 * ```
 */

import * as stylex from '@stylexjs/stylex';
import {reducedMotionFadeConsts} from '../motion/reducedMotion.stylex';
import {durationVars, easeVars, spacingVars} from '@astryxdesign/core/theme/tokens.stylex';

const enterBelow = stylex.keyframes({
  from: {
    opacity: 0,
    transform: `translateY(calc(-1 * ${spacingVars['--spacing-2']})) scale(0.95)`,
  },
  to: {opacity: 1, transform: 'translateY(0) scale(1)'},
});

const enterAbove = stylex.keyframes({
  from: {
    opacity: 0,
    transform: `translateY(${spacingVars['--spacing-2']}) scale(0.95)`,
  },
  to: {opacity: 1, transform: 'translateY(0) scale(1)'},
});

const enterEnd = stylex.keyframes({
  from: {
    opacity: 0,
    transform: `translateX(calc(-1 * ${spacingVars['--spacing-2']})) scale(0.95)`,
  },
  to: {opacity: 1, transform: 'translateX(0) scale(1)'},
});

const enterStart = stylex.keyframes({
  from: {
    opacity: 0,
    transform: `translateX(${spacingVars['--spacing-2']}) scale(0.95)`,
  },
  to: {opacity: 1, transform: 'translateX(0) scale(1)'},
});

// RTL: the horizontal entrance nudge is a physical translateX, so it must
// mirror under RTL — a layer on the inline-end/start side must slide in from
// the correct physical side following the reading flow. Only the horizontal
// (translateX) keyframes need mirroring; the vertical enterAbove/enterBelow
// (translateY) entrances are direction-neutral and are left as-is.
const enterEndRtl = stylex.keyframes({
  from: {
    opacity: 0,
    transform: `translateX(${spacingVars['--spacing-2']}) scale(0.95)`,
  },
  to: {opacity: 1, transform: 'translateX(0) scale(1)'},
});

const enterStartRtl = stylex.keyframes({
  from: {
    opacity: 0,
    transform: `translateX(calc(-1 * ${spacingVars['--spacing-2']})) scale(0.95)`,
  },
  to: {opacity: 1, transform: 'translateX(0) scale(1)'},
});

// Reduce Motion under a finger: the same entrance without its travel. A touch
// presentation substitutes a cross-fade for motion, never a jump.
// The fade's curve rides in its first keyframe, so the published class type
// of `animationTimingFunction` stays the theme ease's.
const fadeIn = stylex.keyframes({
  from: {opacity: 0, animationTimingFunction: reducedMotionFadeConsts.easing},
  to: {opacity: 1},
});

// No theme value lengthens the Reduce Motion fade, so its values are constants.
// The media keys stay literal: StyleX gives an imported at-rule key a later
// priority layer (see reducedMotionKeys).
const animationBase = {
  animationDuration: {
    default: durationVars['--duration-fast-max'],
    '@media (prefers-reduced-motion: reduce) and (pointer: coarse)':
      reducedMotionFadeConsts.duration,
  },
  animationTimingFunction: easeVars['--ease-standard'],
  animationFillMode: 'backwards' as const,
};

/**
 * Shared entry animation styles for layer-based components.
 *
 * Keyed by LayerPlacement ('above' | 'below' | 'start' | 'end')
 * for easy lookup: `layerAnimations[placement]`.
 *
 * Under `prefers-reduced-motion: reduce` each entry drops its travel and
 * scale. Under a finger (the primary pointer is coarse) the layer fades in,
 * opacity only, in 200 ms on easeInOut: on a touch screen Reduce Motion
 * replaces motion with a cross-fade rather than a jump; under any other
 * pointer it appears at once.
 */
export const layerAnimations = stylex.create({
  below: {
    animationName: {
      default: enterBelow,
      '@media (prefers-reduced-motion: reduce) and (not (pointer: coarse))':
        'none',
      '@media (prefers-reduced-motion: reduce) and (pointer: coarse)': fadeIn,
    },
