function onLayoutGrid(value: number): number {
  const snapped = Math.round(value * LAYOUT_UNITS_PER_PX) / LAYOUT_UNITS_PER_PX;
  return Math.abs(snapped - value) < GRID_TOLERANCE_PX ? snapped : value;
