      {
        at: 0,
        value: view.hasOpacityCurve ? opacityNow : (borrowed ?? opacityNow),
      },
      {at: ms / 2, value: 0},
    ];
    const landing = landsLater(ms / 2, {
      to: borrowed ?? opacityTo,
      ms: ms / 2,
      isBorrowed: borrowed != null,
    });
