    return `${short(duration)}s ${short(bounce)}`;
  }
  if (kind === 'duration') {
    if (!(typeof value === 'number' && Number.isFinite(value) && value >= 0)) {
      throw new TypeError('a duration is a finite number of milliseconds ≥ 0');
