export function motionRoleIn(
  group: object,
  key: string,
): MotionRole | undefined {
  const prefix = pathOfGroup.get(group);
  if (prefix == null) {
    return undefined;
  }
  const path = `${prefix}.${key}`;
  return rolesById.get(roleIdOfPath.get(path) ?? path);
